import { z } from 'zod'
import { pikkuFunc } from '#pikku/function'
import { NotFoundError } from '#pikku/error'
import { hasProfileRole, isOrderOwner } from '../../wirings/shop.security.js'

export const RequestRefundInput = z.object({
  orderId: z.string(),
  reason: z.string(),
})
export const RequestRefundOutput = z.object({ runId: z.string() })

// The export name is the RPC name. `expose: true` is all a client needs: the
// generated clients call `requestRefund` with no wireHTTP.
export const requestRefund = pikkuFunc({
  expose: true,
  description: 'Ask for a refund on an order.',
  input: RequestRefundInput,
  output: RequestRefundOutput,
  // A map of guards, each from `pikkuPermission`. Any one key passing admits.
  permissions: {
    owner: isOrderOwner,
    support: hasProfileRole({ role: 'support' }),
  },
  // Services, then input, then the wire: `session`, `rpc`, `http`, `channel`.
  func: async ({ kysely, logger }, { orderId, reason }, { session, rpc }) => {
    const order = await kysely
      .selectFrom('order')
      .select('orderId')
      .where('orderId', '=', orderId)
      .executeTakeFirst()
    if (!order) throw new NotFoundError()

    logger.info(`${session.userId} asked to refund ${orderId}`)
    return rpc.startWorkflow('refundWorkflow', { orderId, reason })
  },
})

import { pikkuListFunc } from '#pikku/function'

export const listItemRows = pikkuListFunc<
  { categorySlug: string; inStock: boolean },
  { itemId: string; name: string; priceCents: number; stock: number }
>({
  expose: true,
  description: 'Catalogue rows in the standard list shape (rows + cursor).',
  func: async ({ kysely }, { limit, cursor, search }) => {
    // `limit` comes from the caller, so cap it.
    const pageSize = Math.min(limit ?? 20, 100)
    // The cursor is whatever string the last page handed out; here, an offset.
    const offset = Number(cursor ?? 0)

    let query = kysely
      .selectFrom('item')
      .innerJoin('category', 'category.categoryId', 'item.categoryId')
      .select(['item.itemId', 'item.name', 'item.priceCents', 'item.stock'])
      .where('item.isActive', '=', 1)

    if (search) query = query.where('item.name', 'like', `%${search}%`)

    // One extra row says whether another page exists.
    const rows = await query
      .orderBy('item.itemId')
      .limit(pageSize + 1)
      .offset(offset)
      .execute()

    return {
      rows: rows.slice(0, pageSize),
      nextCursor: rows.length > pageSize ? String(offset + pageSize) : null,
    }
  },
})
